// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    DAO c;
    function setUp() public { c = new DAO(); }
    function testFuzz_property(address proposedAddress, string memory typeStr, address recipient, uint256 amount) public {
        vm.assume(proposedAddress != address(0));
        uint256 idBefore = c.proposalCount();
        c.newAddressProposal(proposedAddress, typeStr);
        c.newGrantProposal(recipient, amount);
        uint256 idAfter = c.proposalCount();
        (address rec, uint256 amt) = c.mapPID_grant(idAfter);
        assertTrue(
            rec == recipient && amt == amount
            && c.mapPID_address(idAfter - 1) == proposedAddress
            && idAfter == idBefore + 2
        );
    }
}
